package io.gitee.mcdull.blaze;

import cn.hutool.core.util.HexUtil;
import cn.hutool.crypto.Mode;
import cn.hutool.crypto.Padding;
import cn.hutool.crypto.symmetric.SM4;
import org.bouncycastle.crypto.engines.SM4Engine;
import org.bouncycastle.crypto.params.KeyParameter;

import java.nio.charset.StandardCharsets;

public class Demo {


    public static void main2(String[] args) {

        String hexCipher = ""; // 取完整 data 字段
        byte[] cipherBytes = HexUtil.decodeHex(hexCipher);

        SM4 sm4 = new SM4(Mode.ECB, Padding.NoPadding, "1234567890abcdef".getBytes());
        byte[] plainBytes = sm4.decrypt(cipherBytes);

// 去掉头部随机填充（第 16 字节表示填充长度）
        int padLen = plainBytes[15] & 0xFF;
        String json = new String(plainBytes, 16 + padLen, plainBytes.length - 16 - padLen, StandardCharsets.UTF_8);
        System.out.println(json);

    }

    public static void main(String[] args) {
        String hexCipher = "a9e126c91a28cc2f6813e379336939a3987fdf03feacb214de44b7bfbd080e244138a2b5d24b967049e65d175636a325f29ee018c04bc7b48cc7a9acba86"; // 你的完整密文
        byte[] cipher = HexUtil.decodeHex(hexCipher);

        SM4Engine engine = new SM4Engine();
        engine.init(false, new KeyParameter("1234567890abcdef".getBytes()));

        int blockSize = engine.getBlockSize();
        byte[] out = new byte[cipher.length];
        for (int i = 0; i < cipher.length; i += blockSize) {
            engine.processBlock(cipher, i, out, i);
        }

        // 去掉头部随机填充
        int padLen = out[15] & 0xFF;
        String json = new String(out, 16 + padLen, out.length - 16 - padLen, StandardCharsets.UTF_8);
        System.out.println(json);
    }

}
